import sys, json, re, hashlib

# THE OBJECT TOOLS OF A MODEL (GH #951): one `tool_call` in on `in_tool`, one
# `tool_result` out under the call's id -- the shape of the file space's tool
# adapter (GH #908). Reads are served here from the store (`object_find`,
# `object_brief` through `./brief`); a change (`object_set`, `object_confirm`)
# is checked here and written by `./gate`, the one writer, whose answer comes
# back on `answer` under `caller` 'tools'.
#
# THE ROUND DECIDES WHAT EXISTS. The question round is `context.audience_now`
# (the member's tool edge stamps it from `context.audience_set`), else
# `context.audience_set`; without one every call is `missing_audience`. A row
# whose round does not cover the question round answers exactly like a row that
# was never written: `not_found`, byte for byte -- never a hint of existence.
#
# THE OWNER, AND ONLY THE OWNER, says why and decides the state. The owner of a
# turn is `context.speaker` (stamped by the bound 1:1 channel with proof of the
# sender, `member:<person>`) when it is a `member:` reference, stands in the
# round of the turn, and equals the param `owner` when that is set. A missing
# speaker (an unbound channel, a peer, a timer) is no owner: `why`, `state`
# and `object_confirm` answer `owner_only`, fail-closed. `context.user_id` and
# plain membership in the round are no substitute.
ME = "tools"


def _int(key, default):
    v = P.get(key, default) if isinstance(P, dict) else default
    try:
        return int(float(v))
    except Exception:
        return default


def _types(v):
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            v = [v]
    out = [str(x).strip() for x in (v if isinstance(v, list) else []) if str(x).strip()]
    return out or ["thing"]


doc = json.load(sys.stdin)
P = doc.get("params") or {}
TYPES = _types(P.get("types"))
SLOT_MAX = max(1, _int("slot_max", 400))
OWNER = str(P.get("owner") or "").strip()
SCAN = max(100, _int("scan_max", 5000))

SLOTS = ("what", "where", "who", "when", "why", "how")
FIELDS = SLOTS + ("alias", "type", "state", "doc", "related")
OWNER_FIELDS = ("why", "state")
ID_RE = re.compile(r"^ob-[0-9a-f]{12}$")
COLS = ["id", "rev", "type", "aliases", "state", "origin", "valid_since", "audience_set",
        "slots", "refs", "seen", "turns", "supersedes", "recorded_at"]
FIND_MAX = 20
FIND_IDS = 100
NOT_FOUND = "no such object"

# --8<-- object-offer
# THE OBJECT TOOLS, one list, one entry per tool (GH #951). It stands WORD FOR
# WORD in `./schemas` (which hands it to a model's menu) and in `./tools`
# (which checks every call against it), because a code cell has no library it
# could share: `gh951_a_thing_becomes_a_row.rs` holds the two copies to one
# value. The name IS the mapping: `object_<op>`.
OID = {"type": "string",
       "description": "the object: its address `ob-<12 hex>`, as `object_find` names it"}


def _obj(props, required):
    return {"type": "object", "properties": props, "required": required,
            "additionalProperties": False}


OBJECT_OFFER = [
    {"name": "object_find",
     "description": "Find the objects of this conversation (address `ob-<12 hex>`) whose name "
                    "or alias contains `q` or whose type is `q`, each with its type, main name "
                    "and state.",
     "parameters": _obj({"q": {"type": "string",
                               "description": "a name, a part of a name, or a type"}}, ["q"])},
    {"name": "object_brief",
     "description": "The brief of one object (address `ob-<12 hex>`): its type, main name, "
                    "filled slots and the latest facts about it.",
     "parameters": _obj({"id": OID}, ["id"])},
    {"name": "object_set",
     "description": "Set one field of an object (address `ob-<12 hex>`): a slot `what`, `where`, "
                    "`who` (a person reference like `member:<id>`, never a name), `when`, "
                    "`why` or `how`, or `alias`, `type`, `state`, `doc` (`fh-<12 hex>#<anchor>`) "
                    "or `related` (`ob-<12 hex>`), where only the owner sets `why` and `state`.",
     "parameters": _obj({"id": OID,
                         "slot": {"type": "string", "enum": list(FIELDS),
                                  "description": "the field to set"},
                         "value": {"type": "string",
                                   "description": "the new value; empty clears a slot, `who`, "
                                                  "`doc` or `related`"}},
                        ["id", "slot", "value"])},
    {"name": "object_confirm",
     "description": "Confirm an object (address `ob-<12 hex>`) as real, which makes it active "
                    "at once, and only the owner confirms.",
     "parameters": _obj({"id": OID}, ["id"])},
]
# --8<-- end object-offer

TYPES_OK = {"string": (str,), "integer": (int,), "number": (int, float),
            "boolean": (bool,), "array": (list,), "object": (dict,)}


# --8<-- round
# A round is `audience_set`: the JSON text of a list of strings. Canonical =
# sorted, without duplicates, without empty or non-string entries (GH #951,
# review of the memory seam: an empty name is nobody, and memory's
# `audience_now` must never carry a `""`); nothing left = "[]". Unparsable,
# empty text, not a list or absent = NO round; "[]" is a round (an empty one,
# roundless). `covers` is fail-closed: a row is visible to a question round
# exactly when nobody of the question is missing from the row's round ("*" in
# the row: everybody). A round is never widened.
def canon_round(v):
    if not isinstance(v, str) or not v.strip():
        return None
    try:
        xs = json.loads(v)
    except Exception:
        return None
    if not isinstance(xs, list):
        return None
    xs = [x for x in xs if isinstance(x, str) and x.strip()]
    return json.dumps(sorted(set(xs)), separators=(",", ":"))


def covers(row_aud, q):
    q = canon_round(q)
    r = canon_round(row_aud)
    if q is None or r is None:
        return False
    rs = json.loads(r)
    if "*" in rs:
        return True
    qs = json.loads(q)
    if not qs:
        # A roundless question sees only roundless rows: `set() <= rs` would
        # let it see every row of every round (#951, fail-closed).
        return not rs
    return set(qs) <= set(rs)
# --8<-- end round


# --8<-- norm-key
# The normal form of a name or alias: the memory hive store's `normalize`
# (crates/meclaw-cells/src/store/query/normalize.rs) in python, so that an
# object alias and a fact subject equate the same spellings (M.1). Lower case
# (`str.lower`, as rust `to_lowercase`), then the Latin-1 composition table of
# that file (a combining mark after its ASCII base letter becomes the
# precomposed letter), then trim + every run of whitespace -> one space. The
# whitespace set is rust's `char::is_whitespace` (Unicode White_Space), NOT
# python's `str.split()`, which also splits on U+001C..U+001F. No casefold.
# --8<-- normalize_text (copy of memory-hive writer, GH #948/#951)
# The memory hive's writer carries this function; this block is its copy
# word for word (gh951_one_spelling_one_key.rs), so that an alias and a
# fact subject meet under one key. Swap the whole block, never edit it here.
COMPOSE_ROWS = (
    ("\u0300", "aeiou", "\u00e0\u00e8\u00ec\u00f2\u00f9"),
    ("\u0301", "aeiouy", "\u00e1\u00e9\u00ed\u00f3\u00fa\u00fd"),
    ("\u0302", "aeiou", "\u00e2\u00ea\u00ee\u00f4\u00fb"),
    ("\u0303", "ano", "\u00e3\u00f1\u00f5"),
    ("\u0308", "aeiouy", "\u00e4\u00eb\u00ef\u00f6\u00fc\u00ff"),
    ("\u030a", "a", "\u00e5"),
    ("\u0327", "c", "\u00e7"),
)
COMPOSITIONS = {(base, mark): composed
                for mark, bases, composed_forms in COMPOSE_ROWS
                for base, composed in zip(bases, composed_forms)}
# Rust's `char::is_whitespace` (the Unicode White_Space property), spelled out:
# Python's `str.split()` also splits on U+001C..U+001F, which the store keeps.
WHITE_SPACE = frozenset("\t\n\x0b\x0c\r \x85\xa0\u1680\u2000\u2001\u2002\u2003"
                        "\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029"
                        "\u202f\u205f\u3000")


def normalize_text(value):
    """The normal form of one string -- the twin of `meclaw_norm` (0.2.0 P4).

    Same three effects in the same order as the store: case fold, Latin-1
    composition (NFD -> NFC), whitespace collapse over the store's own
    whitespace. An unrecognised mark leaves the two spellings DIFFERENT, which
    is the same conservatism the Rust side ships.
    """
    out = []
    for ch in str(value or "").lower():
        composed = COMPOSITIONS.get((out[-1], ch)) if out else None
        if composed is None:
            out.append(ch)
        else:
            out[-1] = composed
    words, word = [], []
    for ch in out:
        if ch in WHITE_SPACE:
            if word:
                words.append("".join(word))
                word = []
        else:
            word.append(ch)
    if word:
        words.append("".join(word))
    return " ".join(words)
# --8<-- end normalize_text


def norm_key(s):
    return normalize_text(s)
# --8<-- end norm-key


def loads(v, default):
    if isinstance(v, str):
        try:
            x = json.loads(v)
        except Exception:
            return default
        return x if isinstance(x, type(default)) else default
    return v if isinstance(v, type(default)) else default


def op_of(name):
    """The op of a tool name (`object_<op>`), or None for a name this hive
    does not serve."""
    if not isinstance(name, str) or name not in [t["name"] for t in OBJECT_OFFER]:
        return None
    return name[len("object_"):]


def type_ok(v, t):
    if isinstance(t, list):
        return any(type_ok(v, x) for x in t)
    want = TYPES_OK.get(t)
    if want is None:
        return True
    if isinstance(v, bool) and t != "boolean":
        return False
    return isinstance(v, want)


def check(schema, v, at="arguments"):
    """The problems of `v` against a JSON Schema of the subset `OBJECT_OFFER`
    uses; [] when it holds (the file space's checker, GH #908)."""
    out = []
    t = schema.get("type")
    if t is not None and not type_ok(v, t):
        return ["%s must be %s" % (at, t if isinstance(t, str) else " or ".join(t))]
    if "enum" in schema and v not in schema["enum"]:
        out.append("%s must be one of %s" % (at, ", ".join(map(str, schema["enum"]))))
    if isinstance(v, dict):
        props = schema.get("properties") or {}
        for k in schema.get("required") or []:
            if k not in v:
                out.append("%s.%s is required" % (at, k))
        for k, x in v.items():
            if k in props:
                out.extend(check(props[k], x, "%s.%s" % (at, k)))
            elif schema.get("additionalProperties") is False:
                out.append("%s.%s is not an argument of this tool" % (at, k))
    return out


def question_round(c):
    """`context.audience_now` when the edge stamped one, else
    `context.audience_set`; None = no round."""
    now_ = c.get("audience_now")
    if isinstance(now_, str) and now_.strip():
        return canon_round(now_)
    return canon_round(c.get("audience_set"))


def is_owner(c, round_, owner=None):
    """The speaker of the turn is its owner: a `member:` reference, standing in
    the round of the turn, and the param `owner` when that is set. Fail-closed:
    anything else -- no speaker, no round, `*` -- is no owner."""
    owner = OWNER if owner is None else owner
    sp = c.get("speaker")
    if not isinstance(sp, str) or not sp.startswith("member:") or len(sp) <= len("member:"):
        return False
    if round_ is None or sp not in json.loads(round_):
        return False
    return not owner or sp == owner


def refusal(op, code, message):
    return {"ok": False, "op": op or "", "error": {"code": code, "message": message}}


def result_text(answer):
    keep = {k: v for k, v in answer.items()
            if k not in ("op_id", "caller", "messages", "header")}
    return json.dumps(keep, ensure_ascii=False, sort_keys=True)


def tool_result(call_id, answer):
    head = {"route": "tool_result", "tool_call_id": call_id}
    if answer.get("ok") is False:
        head["error_code"] = str((answer.get("error") or {}).get("code") or "")
    return {"header": head,
            "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                          "text": result_text(answer)}]}


PREFIX = ME + ":"


def call_of(op_id):
    op_id = str(op_id or "")
    return op_id[len(PREFIX):] if op_id.startswith(PREFIX) else op_id


def store(ops, phase, carry):
    return {"header": {"route": "tools_store", "phase": phase, "reply_cell": ME,
                       "cur_call": json.dumps(carry, sort_keys=True, ensure_ascii=False)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(a, ensure_ascii=False)} for cid, a in ops]}


def head_op(oid):
    return {"operation": "select", "table": "objects", "columns": COLS,
            "where": {"id": oid}, "order_by": [{"col": "rev", "dir": "desc"}], "limit": 1}


def translate(name, raw, call_id, c):
    """One tool call -> the ONE message this cell emits for it."""
    op = op_of(name)
    if op is None:
        return tool_result(call_id, refusal("", "tool_unknown",
                                            "this hive has no tool %r" % (name,)))
    if isinstance(raw, dict):
        args = raw
    else:
        try:
            args = json.loads(raw or "{}")
        except Exception:
            args = None
    if not isinstance(args, dict):
        return tool_result(call_id, refusal(op, "bad_request",
                                            "the arguments are not a JSON object"))
    schema = [t for t in OBJECT_OFFER if t["name"] == name][0]["parameters"]
    bad = check(schema, args)
    if bad:
        return tool_result(call_id, refusal(op, "bad_request", "; ".join(bad)))
    if not call_id:
        return tool_result(call_id, refusal(op, "bad_request", "the call carries no id"))
    round_ = question_round(c)
    if round_ is None:
        return tool_result(call_id, refusal(op, "missing_audience",
                                            "the call carries no round"))
    if op == "confirm" or (op == "set" and args.get("slot") in OWNER_FIELDS):
        if not is_owner(c, round_):
            return tool_result(call_id, refusal(
                op, "owner_only", "only the owner of this conversation confirms an object, "
                                  "says why, or changes its state"))
    carry = {"op": op, "call_id": call_id, "round": round_}
    if op == "set":
        value = args.get("value")
        if len(value) > SLOT_MAX:
            return tool_result(call_id, refusal(op, "too_long",
                                                "a value holds at most %d characters" % SLOT_MAX))
        if args.get("slot") == "type" and value.strip() not in TYPES:
            return tool_result(call_id, refusal(op, "bad_type",
                                                "the type is one of %s" % ", ".join(TYPES)))
    if op in ("set", "confirm"):
        return {"header": {"route": "edit", "op": op, "op_id": PREFIX + call_id, "caller": ME},
                "op": op, "id": args.get("id"), "slot": args.get("slot") or "",
                "value": args.get("value") or "", "round": round_}
    if op == "brief":
        if not ID_RE.match(args.get("id") or ""):
            return tool_result(call_id, refusal(op, "not_found", NOT_FOUND))
        return store([("h", head_op(args["id"])),
                      ("p", {"operation": "select", "table": "pushes",
                             "columns": ["id", "facts"], "where": {"id": args["id"]},
                             "limit": 1})], "brief-1", dict(carry, id=args["id"]))
    q = str(args.get("q") or "")
    return store([("k", {"operation": "select", "table": "keys", "columns": ["key", "id"],
                         "limit": SCAN}),
                  ("t", {"operation": "select", "table": "objects", "columns": ["id"],
                         "where": {"type": q.strip()}, "limit": SCAN})],
                 "find-1", dict(carry, q=norm_key(q), type=q.strip()))


def legs(body, h):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(h.get("error_code") or "")
    return out


def rows_of(leg):
    p = (leg or {}).get("payload")
    return [r for r in p if isinstance(r, dict)] if isinstance(p, list) else []


def find_items(heads, round_, q, type_):
    """The answer of `object_find`, pure: the visible heads whose alias keys
    contain `q` or whose type is `type_`, oldest first, at most FIND_MAX."""
    out = []
    for r in heads:
        if not covers(r.get("audience_set"), round_):
            continue
        aliases = loads(r.get("aliases"), [])
        if not (any(q in norm_key(a) for a in aliases) or (type_ and r.get("type") == type_)):
            continue
        out.append(r)
    out.sort(key=lambda r: (str(r.get("valid_since") or ""), str(r.get("id") or "")))
    return [{"id": r.get("id"), "type": r.get("type"),
             "name": (loads(r.get("aliases"), []) or [r.get("id")])[0],
             "state": r.get("state")} for r in out[:FIND_MAX]]


def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and "messages" not in m:
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs, ensure_ascii=False))
    sys.exit(0)


d = doc.get("body") or {}
h = (doc.get("envelope") or {}).get("header") or {}
hop = h.get("hop") or {}
ctx = h.get("context") or {}
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "in_tool":
    msgs = d.get("messages") or []
    call = msgs[0] if msgs and isinstance(msgs[0], dict) else {}
    call_id = str(call.get("id") or hop.get("tool_call_id") or "")
    emit([translate(str(hop.get("tool_name") or ""), call.get("text"), call_id, ctx)])

if lane == "answer":
    if str(hop.get("caller") or "") != ME:
        sys.stderr.write("objects/tools: an answer for %r -- dropped\n"
                         % str(hop.get("caller") or ""))
        emit([])
    emit([tool_result(call_of(hop.get("op_id")), d)])

if lane == "rendered":
    c = d.get("carry") if isinstance(d.get("carry"), dict) else {}
    emit([tool_result(str(c.get("call_id") or ""),
                      {"ok": True, "op": "brief", "id": c.get("id"),
                       "text": str(d.get("text") or "")})])

if lane:
    sys.stderr.write("objects/tools: unknown lane %r -- dropped\n" % lane)
    emit([])

c = loads(ctx.get("cur_call"), {})
lg = legs(d, hop)
call_id = str(c.get("call_id") or "")
bad = sorted(k for k, leg in lg.items() if leg["error_code"])
if bad and phase in ("find-1", "find-2", "brief-1"):
    emit([tool_result(call_id, refusal(c.get("op"), "store_error",
                                       "the store refused %s" % ", ".join(bad)))])

if phase == "find-1":
    ids = set()
    for r in rows_of(lg.get("k")):
        if c.get("q", "") in str(r.get("key") or ""):
            ids.add(str(r.get("id") or ""))
    for r in rows_of(lg.get("t")):
        ids.add(str(r.get("id") or ""))
    ids = sorted(i for i in ids if ID_RE.match(i))[:FIND_IDS]
    if not ids:
        emit([tool_result(call_id, {"ok": True, "op": "find", "items": []})])
    emit([store([("h%d" % n, head_op(i)) for n, i in enumerate(ids)], "find-2", c)])

if phase == "find-2":
    heads = [r for leg in lg.values() for r in rows_of(leg)]
    emit([tool_result(call_id, {"ok": True, "op": "find",
                                "items": find_items(heads, c.get("round"), c.get("q", ""),
                                                    c.get("type", ""))})])

if phase == "brief-1":
    head = (rows_of(lg.get("h")) or [None])[0]
    if head is None or not covers(head.get("audience_set"), c.get("round")):
        emit([tool_result(call_id, refusal("brief", "not_found", NOT_FOUND))])
    facts = loads(((rows_of(lg.get("p")) or [{}])[0]).get("facts"), [])
    emit([{"header": {"route": "brief_render", "reply_cell": ME},
           "row": head, "facts": facts, "carry": c}])

sys.stderr.write("objects/tools: unknown phase %r -- dropped\n" % phase)
emit([])
